&lt;/a&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;Magus&lt;/a&gt;.&lt;/b&gt; Le magus ajoute +1/2 point de d&#233;g&#226;ts &#224; ses sorts du &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;registre&lt;/a&gt; du feu. &lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html&quot; title=&quot;Le m&#233;dium&quot;&gt;M&#233;dium&lt;/a&gt;.&lt;/b&gt; quand il acquiert un &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#TABOU&quot; title=&quot;Le m&#233;dium&quot;&gt;tabou&lt;/a&gt;, le m&#233;dium peut utiliser l’&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#ACC&#200;SDEPUISSANCESPIRITUELLE&quot; title=&quot;Le m&#233;dium&quot;&gt;acc&#232;s de puissance spirituelle&lt;/a&gt; sans subir d’&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#ESPRIT&quot; title=&quot;Le m&#233;dium&quot;&gt;influence&lt;/a&gt; 1/4 fois de plus par jour.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
